    let words = tokenize(text);
    let mut counts = count(&words);
    drop_rare(&mut counts, min);
    let mut lines: Vec<String> = vec![
        format!("words: {}", words.len()),
        format!("unique: {}", counts.len()),
        format!("longest: {}", longest(&words).unwrap_or("-")),
    ];
